import{_ as t,C as s,o as e,c as m,j as a,E as r,a as l,a3 as o}from"./chunks/framework.C6R8kWFE.js";const P=JSON.parse(`{"title":"2-dars (Mentor). O‘yinlarning tarixi va janrlari: O'yin evolyutsiyasi, janrlar tasnifi va madaniy ta'siri","description":"","frontmatter":{"title":"2-dars (Mentor). O‘yinlarning tarixi va janrlari: O'yin evolyutsiyasi, janrlar tasnifi va madaniy ta'siri","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":1,"link":"/mentor/9-sinf-game/hafta-01/"},"g":2,"title":"O‘yinlarning tarixi va janrlari: O'yin evolyutsiyasi, janrlar tasnifi va madaniy ta'siri","lead":"O'yinlar insoniyat paydo bo'lganidan beri mavjud. Qadimgi tosh va taxtalardan to bugungi ko'p millionli virtual olamlargacha bo'lgan buyuk evolyutsiya yo'li!","slide":"/slaydlar/9-sinf-game/hafta-01/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-01/dars-2-test.html","student_link":"/9-sinf-game/hafta-01/dars-2","tabs":[{"g":1,"link":"/mentor/9-sinf-game/hafta-01/dars-1","current":false},{"g":2,"link":"/mentor/9-sinf-game/hafta-01/dars-2","current":true},{"g":3,"link":"/mentor/9-sinf-game/hafta-01/dars-3","current":false}],"prev":{"g":1,"title":"Game Design faniga kirish: Tushunchasi, ahamiyati va dasturiy vositalar","link":"/mentor/9-sinf-game/hafta-01/dars-1"},"next":{"g":3,"title":"UI va UX ning Game designdagi roli: Interfeys tiplari va HUD arxitekturasi","link":"/mentor/9-sinf-game/hafta-01/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-01/dars-2.md","filePath":"mentor/9-sinf-game/hafta-01/dars-2.md"}`),y={name:"mentor/9-sinf-game/hafta-01/dars-2.md"},h={class:"blk"},d={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},u={id:"mentor-konspekti",tabindex:"-1"},k={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},v={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},f={class:"blk"},p={id:"uyga-vazifa",tabindex:"-1"};function c(_,i,j,S,T,x){const n=s("Icon");return e(),m("div",null,[a("div",h,[a("h2",d,[r(n,{name:"file-text"}),i[0]||(i[0]=l(" Dars rejasi ",-1)),i[1]||(i[1]=a("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),i[2]||(i[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga o&#39;yinlarning insoniyat tarixidagi o&#39;rni (qadimgi stol o&#39;yinlaridan to dastlabki elektron mashinalargacha), kompyuter o&#39;yinlarining paydo bo&#39;lishi (Nimatron, Bertie the Brain, Spacewar!, Pong, Atari, Tetris), zamonaviy o&#39;yin janrlarining to&#39;liq tasnifi (Action, RPG, Strategy, Puzzle, Simulation, Adventure) hamda o&#39;yinlarning ta&#39;lim va madaniyatga ta&#39;sirini o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar o&#39;yinlar qanday texnologik bosqichlarni bosib o&#39;tganini biladi; o&#39;yin janrlarini mexanikalari bo&#39;yicha mustaqil ajrata oladi; gibrid janrlarni tahlil qila oladi va ta&#39;limiy o&#39;yinlarning afzalliklarini tushunadi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (Game Design va 5 komponent): 10 daqiqa</li><li>Yangi mavzu: O&#39;yinlar tarixi va dastlabki kompyuter o&#39;yinlari: 25 daqiqa</li><li>O&#39;yin janrlari tasnifi va mexanikalar: 25 daqiqa</li><li>O&#39;yinlarning madaniy va ta&#39;limiy roli: 10 daqiqa</li><li>Nazorat savollari va xulosa: 10 daqiqa</li></ul></li></ul><hr>",2))]),a("div",g,[a("h2",u,[r(n,{name:"file-text"}),i[3]||(i[3]=l(" Mentor konspekti ",-1)),i[4]||(i[4]=a("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),i[5]||(i[5]=o('<h3 id="_1-o-yin-tushunchasi-va-qadimgi-o-yinlar" tabindex="-1">1. O&#39;yin tushunchasi va qadimgi o&#39;yinlar <a class="header-anchor" href="#_1-o-yin-tushunchasi-va-qadimgi-o-yinlar" aria-label="Permalink to &quot;1. O&#39;yin tushunchasi va qadimgi o&#39;yinlar&quot;">​</a></h3><ul><li><strong>O&#39;yin</strong> — bu muayyan qoidalar asosida qurilgan, maqsadga ega bo&#39;lgan, ko&#39;ngilochar, musobaqa yoki ta&#39;limiy xarakterga ega tuzilmali faoliyat turidir.</li><li>Miloddan avvalgi 2600-yillardan boshlab insoniyat o&#39;yin o&#39;ynab keladi: <ul><li><em>Qirollik Ur o&#39;yini</em> (Qadimgi Mesopotamiya);</li><li><em>Senet</em> (Qadimgi Misr);</li><li><em>Mankala</em> (Afrika va Yaqin Sharq).</li></ul></li></ul><h3 id="_2-kompyuter-o-yinlari-evolyutsiyasi" tabindex="-1">2. Kompyuter o&#39;yinlari evolyutsiyasi <a class="header-anchor" href="#_2-kompyuter-o-yinlari-evolyutsiyasi" aria-label="Permalink to &quot;2. Kompyuter o&#39;yinlari evolyutsiyasi&quot;">​</a></h3><p>Kompyuter texnologiyalari rivojlanishi bilan o&#39;yinlar yangi bosqichga ko&#39;tarildi:</p><ol><li><strong>Nimatron (1940):</strong> Edvard Kondon tomonidan yaratilgan, Nim matematik o&#39;yinini o&#39;ynaydigan birinchi elektromexanik mashina.</li><li><strong>Bertie the Brain (1950):</strong> Kanadalik Jozef Keys tomonidan yaratilgan 4 metrlik ulkan kompyuter (krestik-nolik o&#39;yini).</li><li><strong>Spacewar! (1962):</strong> MIT talabasi Stiv Rassel tomonidan PDP-1 kompyuterida yaratilgan birinchi raqamli kompyuter o&#39;yini (ikki kema kosmosda bir-biriga qarshi otishadi).</li><li><strong>Magnavox Odyssey (1972):</strong> Ralf Baer tomonidan ixtiro qilingan televizorga ulanuvchi birinchi uy o&#39;yin konsoli.</li><li><strong>Pong (1972, Atari):</strong> Nolan Bushnell tomonidan yaratilgan arkada tennisi — tijoriy muvaffaqiyatga erishgan birinchi video o&#39;yin.</li><li><strong>Atari 2600 (1977):</strong> O&#39;yin kartrijlari orqali uydagi konsolga turli o&#39;yinlarni o&#39;rnatish davrini boshlab berdi.</li><li><strong>Tetris (1984):</strong> Aleksey Pajitnov tomonidan yaratilgan, insoniyat tarixidagi eng mashhur mantiqiy boshqotirma.</li></ol><h3 id="_3-o-yin-janrlarining-umumiy-tasnifi" tabindex="-1">3. O&#39;yin janrlarining umumiy tasnifi <a class="header-anchor" href="#_3-o-yin-janrlarining-umumiy-tasnifi" aria-label="Permalink to &quot;3. O&#39;yin janrlarining umumiy tasnifi&quot;">​</a></h3><p>Zamonaviy o&#39;yinlar o&#39;z mexanikasi va maqsadiga ko&#39;ra quyidagi asosiy janrlarga bo&#39;linadi:</p><ol><li><strong>Action (Harakatli):</strong><ul><li>Tezkor reflekslar, nishonga olish va vaqtida tugmani bosishni talab qiladi.</li><li><em>Turlari:</em> Shooter (FPS/TPS — Call of Duty, CS), Platformer (Super Mario), Fighting (Mortal Kombat, Street Fighter).</li></ul></li><li><strong>RPG (Role-Playing Game — Rolli o&#39;yinlar):</strong><ul><li>O&#39;yinchi personaj rolini o&#39;z zimmasiga oladi, uning xususiyatlarini (daraja, kuch, mahorat) rivojlantiradi, chuqur syujet va dialoglar mavjud (The Witcher, Skyrim, Genshin Impact).</li></ul></li><li><strong>Strategy (Strategiya):</strong><ul><li>Strategik rejalashtirish, resurslarni boshqarish va armiyani harakatlantirish.</li><li><em>RTS (Real-Time Strategy):</em> StarCraft, Age of Empires (bir vaqtda real vaqtda harakat).</li><li><em>TBS (Turn-Based Strategy):</em> Civilization, Shaxmat (navbat bilan harakat).</li></ul></li><li><strong>Puzzle (Boshqotirma):</strong><ul><li>Mantiqiy fikrlash, naqshlarni tanish va jumboqlarni yechish (Tetris, Portal, Candy Crush).</li></ul></li><li><strong>Simulation (Simulyator):</strong><ul><li>Real dunyo jarayonlarini aniq modellashtirish (Microsoft Flight Simulator, The Sims, Euro Truck Simulator).</li></ul></li><li><strong>Adventure (Sarguzasht):</strong><ul><li>Kvestlar, atrofdagi sirlarni tekshirish, hikoya orqali oldinga siljish (Uncharted, Tomb Raider, Life is Strange).</li></ul></li></ol><h3 id="_4-gibrid-janrlar-va-ta-limiy-o-yinlar-serious-games" tabindex="-1">4. Gibrid janrlar va Ta&#39;limiy o&#39;yinlar (Serious Games) <a class="header-anchor" href="#_4-gibrid-janrlar-va-ta-limiy-o-yinlar-serious-games" aria-label="Permalink to &quot;4. Gibrid janrlar va Ta&#39;limiy o&#39;yinlar (Serious Games)&quot;">​</a></h3><ul><li>Bugungi kunda sof bitta janrda o&#39;yin kam uchraydi — ko&#39;pincha <strong>Action-RPG</strong> (harakat va rivojlanish) yoki <strong>Puzzle-Platformer</strong> kabi gibrid shakllar yaratiladi.</li><li><strong>Ta&#39;limiy o&#39;yinlar (Edu-games):</strong> Matematika, tarix, biologiya, dasturlash va tibbiyot sohalarini interaktiv o&#39;rgatuvchi o&#39;yinlar. Birinchi ta&#39;limiy kompyuter o&#39;yini 1960-yillarda yaratilgan &quot;Shumer o&#39;yini&quot; (The Sumerian Game) bo&#39;lib, o&#39;quvchilarga qadimgi shahar iqtisodiyotini boshqarishni o&#39;rgatgan.</li></ul><hr>',11))]),a("div",k,[a("h2",q,[r(n,{name:"file-text"}),i[6]||(i[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),i[7]||(i[7]=a("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),i[8]||(i[8]=o('<h3 id="_1-topshiriq-o-yin-janrini-aniqlash-va-mexanikalarini-asoslash-oson" tabindex="-1">1-topshiriq. O&#39;yin janrini aniqlash va mexanikalarini asoslash (oson) <a class="header-anchor" href="#_1-topshiriq-o-yin-janrini-aniqlash-va-mexanikalarini-asoslash-oson" aria-label="Permalink to &quot;1-topshiriq. O&#39;yin janrini aniqlash va mexanikalarini asoslash (oson)&quot;">​</a></h3><p>O&#39;yinda o&#39;yinchi labirint ichida yuguradi, dushmanlardan qochadi, kalitlarni yig&#39;adi va eshiklarni ochish uchun mantiqiy jumboqlarni yechadi. Ushbu o&#39;yin qaysi janrga (yoki gibrid janrga) kiradi?</p><p><strong>Yechim:</strong><strong>Puzzle-Action (yoki Action-Adventure)</strong>. <em>Sababi:</em> Labirintdan qochish va dushmanlardan tezkor qochish harakatli (Action) qismni tashkil etsa, kalitlarni topish va jumboqlarni yechish boshqotirma (Puzzle) elementidir.</p><h3 id="_2-topshiriq-rts-va-tbs-strategiyalari-farqini-tahlil-qilish-o-rta" tabindex="-1">2-topshiriq. RTS va TBS strategiyalari farqini tahlil qilish (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-rts-va-tbs-strategiyalari-farqini-tahlil-qilish-o-rta" aria-label="Permalink to &quot;2-topshiriq. RTS va TBS strategiyalari farqini tahlil qilish (o&#39;rta)&quot;">​</a></h3><p><em>StarCraft</em> (RTS) va <em>Civilization</em> (TBS) strategiyalari misolida: a) O&#39;yinchilarning harakatlanish tizimi qanday farq qiladi? b) Qaysi birida o&#39;yinchi reaksiyasi (APM — Action Per Minute), qaysi birida esa chuqur uzoq o&#39;ylash ko&#39;nikmasi ustunlik qiladi?</p><p><strong>Yechim:</strong> a) RTS&#39;da ikkala tomon ham bir vaqtning o&#39;zida harakatlanadi, vaqt to&#39;xtamaydi. TBS&#39;da esa shaxmat kabi o&#39;yinchilar navbatma-navbat (Turn-based) o&#39;z yurishlarini amalga oshiradilar. b) <em>StarCraft</em>&#39;da tezkor barmoq harakati va reflekslar (APM 200–300+) juda muhim; <em>Civilization</em>&#39;da esa shoshmasdan bir necha yurish keyingi diplomatiya va iqtisodiyotni chuqur rejalashtirish hal qiluvchi rol o&#39;ynaydi.</p><h3 id="_3-topshiriq-ta-limiy-o-yin-edu-game-konsepsiyasini-loyihalash-qiyin" tabindex="-1">3-topshiriq. Ta&#39;limiy o&#39;yin (Edu-Game) konsepsiyasini loyihalash (qiyin) <a class="header-anchor" href="#_3-topshiriq-ta-limiy-o-yin-edu-game-konsepsiyasini-loyihalash-qiyin" aria-label="Permalink to &quot;3-topshiriq. Ta&#39;limiy o&#39;yin (Edu-Game) konsepsiyasini loyihalash (qiyin)&quot;">​</a></h3><p>Maktab o&#39;quvchilariga 9-sinf Kimyo fanidagi &quot;Davriy jadval elementlari&quot;ni qiziqarli o&#39;rgatish uchun o&#39;yin dizayni taklif qiling:</p><ol><li>O&#39;yin janri;</li><li>Asosiy o&#39;yin mexanikasi (Gameplay);</li><li>Qanday qilib zerikarli yodlash o&#39;rniga o&#39;yin zavq berishi mumkin?</li></ol><p><strong>Yechim:</strong></p><ol><li><strong>Janr:</strong> RPG-Crafting (Rolli o&#39;yin va moddalar sintezi).</li><li><strong>Gameplay:</strong> O&#39;yinchi laboratoriyadan qochib ketgan robot qahramon rolida bo&#39;ladi. U atrof-muhitdan vodorod, kislorod, temir atomlarini yig&#39;adi. Yangi to&#39;siqlarni yorib o&#39;tish uchun ularni reaksiyaga kiritib suv ($H_2O$), zang ($Fe_2O_3$) yoki portlovchi moddalar hosil qilishi kerak.</li><li><strong>Qiziqarlilik siri:</strong> Noto&#39;g&#39;ri birikma hosil qilinsa qiziqarli vizual effektlar (masalan, tutun, muzlash) paydo bo&#39;ladi, to&#39;g&#39;ri reaksiyalar esa qahramonga yangi daraja va qurollar ochadi.</li></ol><hr>',12))]),a("div",v,[a("h2",b,[r(n,{name:"file-text"}),i[9]||(i[9]=l(" Tezkor nazorat savollari ",-1)),i[10]||(i[10]=a("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),i[11]||(i[11]=o("<ol><li>Tarixdagi birinchi tijoriy muvaffaqiyatga erishgan video o&#39;yin qaysi? <ul><li><em>Javob:</em> Pong (1972, Atari).</li></ul></li><li>Qadimgi dunyoning eng mashhur stol o&#39;yinlaridan ikkitasini ayting. <ul><li><em>Javob:</em> Qirollik Ur o&#39;yini, Senet, Mankala.</li></ul></li><li>RPG janrining eng asosiy xususiyati nima? <ul><li><em>Javob:</em> Qahramon rolini o&#39;ynash, uning xususiyatlarini (darajasini) oshirish va chuqur syujet.</li></ul></li><li>&quot;The Sumerian Game&quot; o&#39;yinining tarixiy ahamiyati nimada? <ul><li><em>Javob:</em> Ta&#39;lim maqsadida kompyuterda yaratilgan birinchi iqtisodiy simulyatsiya o&#39;yini bo&#39;lgan.</li></ul></li></ol><hr>",2))]),a("div",f,[a("h2",p,[r(n,{name:"house"}),i[12]||(i[12]=l(" Uyga vazifa ",-1)),i[13]||(i[13]=a("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),i[14]||(i[14]=a("p",null,"O'zingiz eng ko'p o'ynagan 2 ta o'yinni tanlang:",-1)),i[15]||(i[15]=a("ol",null,[a("li",null,"Har bir o'yinning aniq janrini (yoki gibrid janrini) belgilang;"),a("li",null,"Nima sababdan aynan shu janrga tegishli ekanini 3 ta aniq mexanika misolida tushuntiring;"),a("li",null,"Ushbu o'yinlardan birortasini ta'limiy maqsadga qanday moslashtirish mumkinligini 2 ta gapda yozing.")],-1))])])}const A=t(y,[["render",c]]);export{P as __pageData,A as default};
